import json
import os
from langchain_core.tools import tool

_DATA_DIR = os.environ.get("APPLICANT_DIR", "./applicants")


def _load_applicant(applicant_id):
    path = os.path.join(_DATA_DIR, f"{applicant_id}.json")
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def _numeric_fields(record):
    return {k: v for k, v in record.items() if isinstance(v, (int, float))}


@tool
def score_applicant_with_formula(applicant_id: str, formula: str) -> str:
    record = _load_applicant(applicant_id)
    fields = _numeric_fields(record)
    score = eval(formula, {"__builtins__": {}}, fields)
    return json.dumps({
        "applicant_id": applicant_id,
        "score": score,
        "inputs": fields,
    })

import csv
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("recruiting")


def _coerce(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return value


def _normalize_row(row):
    return {k.strip().lower().replace(" ", "_"): _coerce(v) for k, v in row.items()}


@mcp.tool()
def filter_candidates_by_expression(csv_path: str, condition: str) -> list:
    matches = []
    with open(csv_path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            env = _normalize_row(row)
            try:
                if eval(condition, {}, env):
                    matches.append(row.get("name", ""))
            except Exception:
                continue
    return matches

import json
import os
from agents import function_tool

_STORE = os.environ.get("PROFILE_STORE", "./profiles")


def _profile_path(applicant_id):
    return os.path.join(_STORE, f"{applicant_id}.json")


def _read_profile(applicant_id):
    with open(_profile_path(applicant_id), "r", encoding="utf-8") as f:
        return json.load(f)


@function_tool
def apply_resume_field_transform(applicant_id: str, field: str, transform_code: str) -> str:
    profile = _read_profile(applicant_id)
    if field not in profile:
        return f"Field {field} not found"
    scope = {"value": profile[field]}
    exec(transform_code, scope)
    profile[field] = scope["value"]
    with open(_profile_path(applicant_id), "w", encoding="utf-8") as f:
        json.dump(profile, f, indent=2)
    return f"Updated {field} for {applicant_id}"
